/**
 * Show the chips row of the template input bar only while one of its chips is on.
 *
 * @module     local_coursegen/local/courseai/template/chips_row
 * @copyright  2026 Wilber Narvaez <https://datacurso.com>
 * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */

/**
 * Show or hide the row according to its chips.
 */
export const refreshChipsRow = () => {
    const chipsRow = document.getElementById('tplChipsRow');
    if (!chipsRow) {
        return;
    }
    const anyChip = Array.from(chipsRow.querySelectorAll('.chip')).some((chip) => !chip.classList.contains('hidden'));
    chipsRow.style.display = anyChip ? '' : 'none';
};
